PRODUCTION_SOURCE = '"""\nOLA-033\nOracle Canonical Market Lineage Ledger\n\nDeterministic per-market lineage state boundary above OLA-031 and OLA-032.\n\nOwns:\n- current lineage head per exact source + market identity\n- independent lineage continuity across interleaved markets\n- one immutable OLA-032 lineage record per accepted fingerprint frame\n- deterministic replay from ordered fingerprint frames\n- fail-closed duplicate observation identity\n- fail-closed per-market clock regression\n\nDoes not own persistence, intelligence interpretation, scoring, alerts,\nQ Series handoff, authorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom types import MappingProxyType\nfrom typing import Iterable, Mapping\n\nfrom .oracle_canonical_dwell_change_lineage_contract import (\n    CanonicalMarketStateDwellChangeLineage,\n    OracleCanonicalDwellChangeLineageContract,\n)\nfrom .oracle_canonical_market_state_fingerprint_contract import (\n    CanonicalMarketStateFingerprint,\n)\n\n\nSCHEMA_VERSION = "OLA-033"\nENGINE_ID = "OLA-033"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass MarketLineageLedgerContractError(ValueError):\n    """Raised when OLA-033 ledger input is malformed."""\n\n\nclass MarketLineageLedgerInvariantError(RuntimeError):\n    """Raised when OLA-033 permanent invariants are violated."""\n\n\n@dataclass(frozen=True, slots=True)\nclass MarketLineageLedgerReceipt:\n    schema_version: str\n    engine_id: str\n    source_id: str\n    source_market_id: str\n    observation_id: str\n    previous_lineage_hash: str | None\n    current_lineage_hash: str\n    current_market_state_hash: str\n    transition_detected: bool\n    consecutive_frame_count: int\n    dwell_seconds: str\n    ledger_market_count: int\n    ledger_record_count: int\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise MarketLineageLedgerInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise MarketLineageLedgerInvariantError(\n                "engine identity invariant violated"\n            )\n        if self.ledger_market_count <= 0:\n            raise MarketLineageLedgerInvariantError(\n                "ledger market count must be positive"\n            )\n        if self.ledger_record_count <= 0:\n            raise MarketLineageLedgerInvariantError(\n                "ledger record count must be positive"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise MarketLineageLedgerInvariantError(\n                "OLA-033 read-only authority invariants violated"\n            )\n\n\n@dataclass(frozen=True, slots=True)\nclass MarketLineageReplayFrame:\n    fingerprint: CanonicalMarketStateFingerprint\n    frame_observed_at: datetime\n\n\nclass OracleCanonicalMarketLineageLedger:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(self) -> None:\n        self._lineage_contract = (\n            OracleCanonicalDwellChangeLineageContract()\n        )\n        self._heads: dict[\n            tuple[str, str],\n            CanonicalMarketStateDwellChangeLineage,\n        ] = {}\n        self._records: list[\n            CanonicalMarketStateDwellChangeLineage\n        ] = []\n        self._seen_observation_ids: set[str] = set()\n\n    @staticmethod\n    def _market_key(\n        fingerprint: CanonicalMarketStateFingerprint,\n    ) -> tuple[str, str]:\n        if not isinstance(\n            fingerprint,\n            CanonicalMarketStateFingerprint,\n        ):\n            raise MarketLineageLedgerContractError(\n                "fingerprint must be an OLA-031 "\n                "CanonicalMarketStateFingerprint"\n            )\n\n        fingerprint.assert_invariants()\n\n        return (\n            fingerprint.source_id,\n            fingerprint.source_market_id,\n        )\n\n    def append(\n        self,\n        *,\n        fingerprint: CanonicalMarketStateFingerprint,\n        frame_observed_at: datetime,\n    ) -> MarketLineageLedgerReceipt:\n        key = self._market_key(fingerprint)\n\n        if fingerprint.observation_id in self._seen_observation_ids:\n            raise MarketLineageLedgerContractError(\n                "duplicate observation_id rejected"\n            )\n\n        previous = self._heads.get(key)\n\n        lineage = self._lineage_contract.observe(\n            current_fingerprint=fingerprint,\n            current_frame_observed_at=frame_observed_at,\n            previous_lineage=previous,\n        )\n\n        lineage.assert_invariants()\n\n        if previous is None:\n            if lineage.previous_lineage_hash is not None:\n                raise MarketLineageLedgerInvariantError(\n                    "new market lineage cannot reference prior head"\n                )\n        else:\n            if lineage.previous_lineage_hash != previous.lineage_hash:\n                raise MarketLineageLedgerInvariantError(\n                    "lineage head continuity invariant violated"\n                )\n\n        self._heads[key] = lineage\n        self._records.append(lineage)\n        self._seen_observation_ids.add(fingerprint.observation_id)\n\n        receipt = MarketLineageLedgerReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            source_id=lineage.source_id,\n            source_market_id=lineage.source_market_id,\n            observation_id=lineage.observation_id,\n            previous_lineage_hash=lineage.previous_lineage_hash,\n            current_lineage_hash=lineage.lineage_hash,\n            current_market_state_hash=(\n                lineage.current_market_state_hash\n            ),\n            transition_detected=lineage.transition_detected,\n            consecutive_frame_count=(\n                lineage.consecutive_frame_count\n            ),\n            dwell_seconds=lineage.dwell_seconds,\n            ledger_market_count=len(self._heads),\n            ledger_record_count=len(self._records),\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=(\n                EXECUTION_ADAPTER_RESOLVED\n            ),\n            execution_adapter_invoked=(\n                EXECUTION_ADAPTER_INVOKED\n            ),\n            trade_authorization_allowed=(\n                TRADE_AUTHORIZATION_ALLOWED\n            ),\n            order_placement_allowed=(\n                ORDER_PLACEMENT_ALLOWED\n            ),\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n        )\n\n        receipt.assert_invariants()\n        return receipt\n\n    def head(\n        self,\n        *,\n        source_id: str,\n        source_market_id: str,\n    ) -> CanonicalMarketStateDwellChangeLineage | None:\n        return self._heads.get(\n            (\n                source_id,\n                source_market_id,\n            )\n        )\n\n    def heads(\n        self,\n    ) -> Mapping[\n        tuple[str, str],\n        CanonicalMarketStateDwellChangeLineage,\n    ]:\n        return MappingProxyType(dict(self._heads))\n\n    def records(\n        self,\n    ) -> tuple[\n        CanonicalMarketStateDwellChangeLineage,\n        ...,\n    ]:\n        return tuple(self._records)\n\n    @property\n    def market_count(self) -> int:\n        return len(self._heads)\n\n    @property\n    def record_count(self) -> int:\n        return len(self._records)\n\n    @classmethod\n    def replay(\n        cls,\n        frames: Iterable[MarketLineageReplayFrame],\n    ) -> "OracleCanonicalMarketLineageLedger":\n        ledger = cls()\n\n        for frame in frames:\n            if not isinstance(frame, MarketLineageReplayFrame):\n                raise MarketLineageLedgerContractError(\n                    "replay frames must be "\n                    "MarketLineageReplayFrame records"\n                )\n\n            ledger.append(\n                fingerprint=frame.fingerprint,\n                frame_observed_at=frame.frame_observed_at,\n            )\n\n        return ledger\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_canonical_market_lineage_ledger import (\n    MarketLineageLedgerContractError,\n    MarketLineageReplayFrame,\n    OracleCanonicalMarketLineageLedger,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_canonical_market_state_fingerprint_contract import (\n    OracleCanonicalMarketStateFingerprintContract,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 6, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 6, 0, 10, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 14, 6, 0, 20, tzinfo=timezone.utc)\nT4 = datetime(2026, 7, 14, 6, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_fingerprint(\n    *,\n    market_id,\n    frame_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    observation = CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id="batch.ola.033." + frame_id,\n    )\n\n    return (\n        OracleCanonicalMarketStateFingerprintContract()\n        .fingerprint(observation=observation)\n    )\n\n\ndef build_frames():\n    return (\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-A",\n                frame_id="a1",\n            ),\n            frame_observed_at=T1,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-B",\n                frame_id="b1",\n            ),\n            frame_observed_at=T1,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-A",\n                frame_id="a2",\n            ),\n            frame_observed_at=T2,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-B",\n                frame_id="b2",\n            ),\n            frame_observed_at=T2,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-A",\n                frame_id="a3",\n                yes_ask="0.7000",\n            ),\n            frame_observed_at=T3,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-B",\n                frame_id="b3",\n            ),\n            frame_observed_at=T3,\n        ),\n        MarketLineageReplayFrame(\n            fingerprint=build_fingerprint(\n                market_id="KXTEST-A",\n                frame_id="a4",\n                yes_ask="0.7000",\n            ),\n            frame_observed_at=T4,\n        ),\n    )\n\n\ndef run_interleaved_market_test():\n    ledger = OracleCanonicalMarketLineageLedger()\n    receipts = []\n\n    for frame in build_frames():\n        receipts.append(\n            ledger.append(\n                fingerprint=frame.fingerprint,\n                frame_observed_at=frame.frame_observed_at,\n            )\n        )\n\n    head_a = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-A",\n    )\n    head_b = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-B",\n    )\n\n    assert head_a is not None\n    assert head_b is not None\n    assert ledger.market_count == 2\n    assert ledger.record_count == 7\n\n    assert head_a.consecutive_frame_count == 2\n    assert head_a.dwell_seconds == "10.000000"\n    assert head_a.state_changed_at == T3\n\n    assert head_b.consecutive_frame_count == 3\n    assert head_b.dwell_seconds == "20.000000"\n    assert head_b.state_changed_at is None\n\n    assert receipts[4].transition_detected is True\n    assert receipts[6].transition_detected is False\n\n    return ledger, receipts, head_a, head_b\n\n\ndef run_per_market_chain_test():\n    ledger, _, head_a, head_b = run_interleaved_market_test()\n\n    records_a = [\n        record\n        for record in ledger.records()\n        if record.source_market_id == "KXTEST-A"\n    ]\n    records_b = [\n        record\n        for record in ledger.records()\n        if record.source_market_id == "KXTEST-B"\n    ]\n\n    assert len(records_a) == 4\n    assert len(records_b) == 3\n\n    for previous, current in zip(records_a, records_a[1:]):\n        assert (\n            current.previous_lineage_hash\n            == previous.lineage_hash\n        )\n\n    for previous, current in zip(records_b, records_b[1:]):\n        assert (\n            current.previous_lineage_hash\n            == previous.lineage_hash\n        )\n\n    assert records_a[-1].lineage_hash == head_a.lineage_hash\n    assert records_b[-1].lineage_hash == head_b.lineage_hash\n\n\ndef run_duplicate_observation_fail_closed_test():\n    ledger = OracleCanonicalMarketLineageLedger()\n    frame = build_frames()[0]\n\n    ledger.append(\n        fingerprint=frame.fingerprint,\n        frame_observed_at=frame.frame_observed_at,\n    )\n\n    try:\n        ledger.append(\n            fingerprint=frame.fingerprint,\n            frame_observed_at=frame.frame_observed_at,\n        )\n        raise AssertionError(\n            "duplicate observation identity must fail closed"\n        )\n    except MarketLineageLedgerContractError:\n        pass\n\n    assert ledger.record_count == 1\n\n\ndef run_per_market_clock_regression_test():\n    ledger = OracleCanonicalMarketLineageLedger()\n\n    first = MarketLineageReplayFrame(\n        fingerprint=build_fingerprint(\n            market_id="KXTEST-CLOCK",\n            frame_id="clock-1",\n        ),\n        frame_observed_at=T3,\n    )\n    second = MarketLineageReplayFrame(\n        fingerprint=build_fingerprint(\n            market_id="KXTEST-CLOCK",\n            frame_id="clock-2",\n        ),\n        frame_observed_at=T2,\n    )\n\n    ledger.append(\n        fingerprint=first.fingerprint,\n        frame_observed_at=first.frame_observed_at,\n    )\n\n    try:\n        ledger.append(\n            fingerprint=second.fingerprint,\n            frame_observed_at=second.frame_observed_at,\n        )\n        raise AssertionError(\n            "per-market clock regression must fail closed"\n        )\n    except MarketLineageLedgerContractError:\n        pass\n\n    assert ledger.record_count == 1\n\n\ndef run_heads_snapshot_test():\n    ledger, _, _, _ = run_interleaved_market_test()\n    snapshot = ledger.heads()\n\n    try:\n        snapshot[\n            (\n                "source.kalshi.market_data",\n                "KXTEST-C",\n            )\n        ] = None\n        raise AssertionError(\n            "head snapshot must be immutable"\n        )\n    except TypeError:\n        pass\n\n    assert ledger.market_count == 2\n\n\ndef run_deterministic_replay_test():\n    frames = build_frames()\n\n    first = OracleCanonicalMarketLineageLedger.replay(frames)\n    second = OracleCanonicalMarketLineageLedger.replay(frames)\n\n    assert first.records() == second.records()\n    assert first.heads() == second.heads()\n    assert first.market_count == second.market_count\n    assert first.record_count == second.record_count\n\n    return first\n\n\ndef main():\n    ledger, receipts, head_a, head_b = (\n        run_interleaved_market_test()\n    )\n\n    run_per_market_chain_test()\n    run_duplicate_observation_fail_closed_test()\n    run_per_market_clock_regression_test()\n    run_heads_snapshot_test()\n\n    replayed = run_deterministic_replay_test()\n\n    result = {\n        "schema_version": receipts[-1].schema_version,\n        "engine_id": receipts[-1].engine_id,\n        "status": "passed",\n        "ola_031_fingerprints_consumed": True,\n        "ola_032_lineage_contract_consumed": True,\n        "per_market_lineage_heads_owned": True,\n        "interleaved_market_frames_isolated": True,\n        "market_count": ledger.market_count,\n        "record_count": ledger.record_count,\n        "market_a_transition_preserved": (\n            head_a.state_changed_at == T3\n        ),\n        "market_a_post_transition_dwell_preserved": (\n            head_a.dwell_seconds == "10.000000"\n        ),\n        "market_b_same_state_dwell_preserved": (\n            head_b.dwell_seconds == "20.000000"\n        ),\n        "per_market_immutable_chain_preserved": True,\n        "duplicate_observation_identity_fails_closed": True,\n        "per_market_clock_regression_fails_closed": True,\n        "immutable_head_snapshot": True,\n        "deterministic_replay_valid": (\n            replayed.records() == ledger.records()\n        ),\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": receipts[-1].read_only,\n        "execution_allowed": receipts[-1].execution_allowed,\n        "execution_adapter_resolved": (\n            receipts[-1].execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            receipts[-1].execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            receipts[-1].trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            receipts[-1].order_placement_allowed\n        ),\n        "funds_moved": receipts[-1].funds_moved,\n        "portfolio_mutated": receipts[-1].portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-033 Oracle Canonical Market "\n        "Lineage Ledger"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-033 INSTALLER")
    print(" ORACLE CANONICAL MARKET LINEAGE LEDGER")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-033 Oracle Canonical Market "
        "Lineage Ledger installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_033_oracle_canonical_"
        "market_lineage_ledger.py"
    )


if __name__ == "__main__":
    main()
